// ─── Space Tycoon: Finite Demand Pools (Economic PvP Wave E4) ────────────────
// docs/ECONOMY_PVP_2026-08.md §2.1 + §E4 — the wave that ends infinite
// service demand. Every service belongs to a demand market keyed
// (locationId, serviceCategory). Each market has a finite pool D in $/month:
//
//   D = (D_npc + D_derived) × D_mod
//
//   D_npc     — the NPC backdrop floor: authored base per location ×
//               NPC-population scaler that RECEDES as 30-day-active player
//               count grows (NPC_BACKDROP.md: floor, not ceiling).
//   D_derived — demand generated by real economic activity at the location,
//               aggregated across synced profiles: buildings there create
//               power/compute/telecom demand, crewed stations create
//               tourism/insurance demand, ships create launch/logistics
//               demand. Rivals BUILDING at a location grow its demand even
//               as they compete to serve it — agglomeration, like real ports.
//   D_mod     — the season super-cycle bias (economic-seasons.ts), mapped to
//               service categories and bounded ±15%. Deterministic from the
//               season number alone, so server and client agree.
//
// Suppliers split the pool by capacity share (service-pricing.ts is the
// pool-share calculator): saturation means competitors literally take your
// customers; undersupply pays a scarcity premium up to +25%. This REPLACES
// the old global log10 instance-count decay, which is retired.
//
// Boundary (§2 architecture invariant): everything cross-player here is
// computed SERVER-side (hourly cron → LocationDemandPool rows, EMA-smoothed
// on a 7-day horizon so pools shift on the DAILY loop) and delivered to the
// deterministic client tick as a bounded snapshot through the sync pipe —
// exactly how spot prices (marketSnapshot) already flow. This module is
// pure and client-safe (no prisma): the server cron, the sync route, and
// the client's solo/offline fallback all share these functions, which is
// what makes away-catch-up parity and determinism testable.
//
// Solo / logged-out / stale-snapshot players tick against a DETERMINISTIC
// local pool: authored NPC floor (full backdrop — an unsynced world is by
// definition a quiet one) + their OWN activity's derived demand vs. NPC
// supply + their OWN capacity. No cross-player quantity is ever computed
// client-side — the local pool contains only authored constants, world
// clocks, and the player's own save.

import { SERVICE_MAP } from './services';
import { BUILDING_MAP } from './buildings';
import { LOCATION_MAP } from './solar-system';
import { serviceSaturationMultiplier } from './formulas';
import { GAME_START_YEAR } from './server-time';
import { getSuperCycleForSeason } from './economic-seasons';
import type { ServiceType } from './types';

// ─── Service categories (§2.1) ──────────────────────────────────────────────
// `mining_output` services are deliberately EXCLUDED: mined-commodity revenue
// competes through the shared market price + extraction pressure (§2.4/E5),
// not through a service demand pool — pooling it too would double-tax mining.

export type ServiceCategory =
  | 'launch'
  | 'telecom'
  | 'sensor'
  | 'compute'
  | 'power'
  | 'tourism'
  | 'logistics'
  | 'fabrication'
  | 'insurance';

export const SERVICE_CATEGORIES: ServiceCategory[] = [
  'launch', 'telecom', 'sensor', 'compute', 'power', 'tourism', 'logistics', 'fabrication', 'insurance',
];

/** Explicit per-service category assignments where the ServiceType alone is
 *  too coarse (spec §2.1: logistics = depot/debris/nav; insurance is its own
 *  market). Everything else falls back to CATEGORY_BY_SERVICE_TYPE. */
const SERVICE_CATEGORY_OVERRIDES: Record<string, ServiceCategory> = {
  svc_propellant_depot: 'logistics',
  svc_debris_removal: 'logistics',
  svc_navigation: 'logistics',
  svc_space_insurance: 'insurance',
  svc_power_orbital: 'power',
  svc_power_lunar: 'power',
  // M1/F2: svc_propellant_brokerage ("buy cheap fuel at Moon, sell at premium
  // to Mars/Jupiter-bound missions") is logistics/arbitrage in substance, not
  // launch-pad capacity — it was miscategorized into mars_orbit's tiny
  // authored `launch` floor (0.375x flagship, a floor-authoring violation).
  // Recategorizing is the spec's preferred fix over inflating a launch floor
  // that has no other tenant.
  svc_propellant_brokerage: 'logistics',
};

const CATEGORY_BY_SERVICE_TYPE: Partial<Record<ServiceType, ServiceCategory>> = {
  launch_payload: 'launch',
  telecom_service: 'telecom',
  sensor_service: 'sensor',
  ai_datacenter: 'compute',
  tourism: 'tourism',
  fabrication_output: 'fabrication',
  // mining_output intentionally absent → null (handled by §2.4 instead)
};

/** Demand-market category for a service — null for mining_output (exempt). */
export function getServiceCategory(serviceId: string): ServiceCategory | null {
  const override = SERVICE_CATEGORY_OVERRIDES[serviceId];
  if (override) return override;
  const def = SERVICE_MAP.get(serviceId);
  if (!def) return null;
  return CATEGORY_BY_SERVICE_TYPE[def.type] ?? null;
}

/** Canonical market key. */
export function demandPoolKey(locationId: string, category: ServiceCategory): string {
  return `${locationId}:${category}`;
}

export const CATEGORY_LABELS: Record<ServiceCategory, string> = {
  launch: 'Launch', telecom: 'Telecom', sensor: 'Sensor & Ops', compute: 'Compute',
  power: 'Power', tourism: 'Tourism', logistics: 'Logistics', fabrication: 'Fabrication',
  insurance: 'Insurance',
};

// ─── D_npc: the authored NPC backdrop floor (§2.1 / §2.9) ───────────────────
// Authored base demand per (location, category) in $/month. Tuning intent:
// each floor ≈ 2.5-3.5× the flagship service revenue for that market, so a
// FIRST mover is undersupplied (earns the scarcity premium) and the market
// comfortably carries 2-3 suppliers before saturation bites — "LEO telecom
// huge, Titan telecom tiny". Values are the <50-active-player full backdrop;
// npcPopulationScaler recedes them as the server fills up.

// M1/F2 floor-authoring pass: every floor below must be ≥ 2.5x the flagship
// (highest single-instance revenuePerMonth) service placeable in that
// (location, category) market — enforced by
// demand-pools.floor-authoring.test.ts, which iterates BUILDINGS × SERVICES
// the same way the harness's build-menu sweep does. Changed vs. the pre-M1
// authoring: earth_surface.launch 60M→150M (Heavy Launch Pad was saturated
// at N=1); geo.logistics 8M→40M (svc_navigation); lunar_orbit.insurance
// (unauthored → 24M, svc_space_insurance) and lunar_orbit.logistics
// 25M→36M (svc_debris_removal) — both found by the exhaustive sweep, not
// just the two the audit called out by name. mars_orbit.launch is
// unchanged (svc_propellant_brokerage was recategorized to logistics
// instead, see SERVICE_CATEGORY_OVERRIDES above — the preferred fix) and
// mars_orbit.logistics raised 40M→100M for it.
